import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"周易阐真 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"周易阐真 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"zh/classics/chanzhen/045.md","filePath":"zh/classics/chanzhen/045.md"}'),s={name:"zh/classics/chanzhen/045.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！</p></blockquote><h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>初六：系于金柅，贞吉。有攸往，见凶。羸豕孚蹢躅。</p><p>九二：包有鱼，无咎，不利宾。</p><p>九三：臀无肤，其行次且，厉，无大咎。</p><p>九四：包无鱼，起凶。</p><p>九五：以杞包瓜，含章，有陨自天。</p><p>上九：姤其角，吝，无咎。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：天下有风，姤。后以施命诰四方。</p><p>姤者，遇也。上乾天，下巽风，是天下有风也。天造万物而不能鼓万物，得风之吹，而万物莫不兴起，此天借风而遇万物，姤之象也。</p><p>后有见于此，知天与万物相远，不易相遇，得风之吹，不遇者而即遇；为上者与下民相远，不易相遇，有命以诰，不遇者亦能遇。以是施教化之命，诰于四方焉。四方甚远，风俗不一，焉得人人而化之?惟施命，则人人遵其所命，遐迩感化，亦如天下有风，无方不到，无物不入。后，即天也；命，即风也。风到处物起，命到处民化，后亦一天矣。圣人教人之道，亦犹是耳。后诰四方有命，圣人教后世有经书，以经书留后世，学人闻者鼓舞，见者惕厉，方且百世而下，莫不兴起，与圣人相晤对，岂第当时四方而已哉!后也，圣人也，无物不爱，无物不感，皆执天行者也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>柅，音尼。羸，音雷。蹢，直益反。躅，直录反。</p><p>姤者，遇也，不期而相遇之义。卦体一阴而入于五阳之下，五阳而遇一阴，故谓姤。此防阴保阳之卦，承上益卦而来。益者，增其阳之不足也。增其不足，必自一阳增至于六，阳纯全而后已。然阳极必生阴，一阴潜生，阳气即伤，故彖辞所以直谓姤，女壮也。但阳极必阴者，造化顺行后天之道，而能借阴全阳者。</p><p>圣人逆运先天之学，如本卦二五，刚而得中，通权达变，刚中有柔，柔中有刚，可以出入乎阴阳之中，而不为阴阳所拘，用六而不为六所用，如遇女不取，阴气虽壮，终听命于阳气，不但阳气不伤，而且阴气亦渐消化，此防阴之功所由贵也。</p><p>初六，一阴潜生，其力足以敌五阳，如金柅能以止车于不行。修道者守贞不失，防患于早，为吉。若有妄动，自招其阴，则凶。特以一阴进而群阴皆动，如一羸豕，能以引群豕而蹢躅，其机虽微，为害最大。此阴气之始生也。</p><p>九二，刚以柔用，戒慎恐惧，能防始生之阴，如鱼在包中不能为害，其利在主不在宾，盖已伺之于早矣。此防阴于未发也。</p><p>九三，刚而自恃，不能防闲于早，阴气已发，制伏甚难，道心中人心相杂，如臀无肤，其行次且，主宰不定矣。幸其刚而守正，日乾夕惕，危厉自处，可无以阴伤阳之咎矣。此防阴于已发也。</p><p>九四，刚而失守，不能防阴而纵阴，坐观成败，道心有昧，人心乱生，祸起萧墙，如鱼出包中，无所不至矣。此不知防阴而见伤也。</p><p>九五，刚健中正，天人混合，以道心而制人心，如以杞之阳，包瓜之阴，黜聪毁智，光华含内，阴气不得而近之，以是处姤，人力可以回天，阳气不伤，阴气自化矣。此以阳防阴而无伤也。</p><p>上九，刚而高亢，不能防阴于早，阳极必阴，刚极必败，金丹得而复失，自取其咎，与阴无咎。此防阴不早而终伤也。</p><p>六爻或知防阴，或不知防阴，或防阴于早，或防阴于迟。求其防于早，而阴不能生，其惟九二。以阳统阴，使其自消自化，得其中正者，其惟九五乎？防阴得其中正，用六而不为六所用，借阴保阳，不在是乎？</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
